export { HeroBanner } from './heroBanner';
export { DuplexSection } from './duplexSection';
export { VideoEmbed } from './videoEmbed';
export { ProductHero } from './productHero';
export { default as ShoppableImage } from './experiences/shoppableImage';

/** @type {import('../sync').ContentTypeDefinition} */
module.exports = {
  id: 'shoppableImage',
  name: 'Shoppable Image',
  displayField: 'title',
  description: 'An editorial image with product hotspots. Each hotspot links to an SFCC product.',
  fields: [
    {
      id: 'title',
      name: 'Title',
      type: 'Symbol',
      required: true,
    },
    {
      id: 'image',
      name: 'Image',
      type: 'Link',
      linkType: 'Asset',
      required: true,
    },
    {
      id: 'imageAlt',
      name: 'Image Alt Text',
      type: 'Symbol',
      required: false,
    },
    {
      id: 'hotspots',
      name: 'Hotspots',
      type: 'Object',
      required: false,
      // Expected shape:
      // [ { "x": 0–100, "y": 0–100, "productId": "<SFCC master product ID>" }, ... ]
      // e.g. [{ "x": 30, "y": 25, "productId": "ABC12345" }]
    },
  ],
};

